414	+// FetchFeature fetches and parses all artifacts for a single feature from the given ref.
415	+// It builds a path set for the feature's tasks directory to discover all task YAMLs.
416	+func (a *Adapter) FetchFeature(ctx context.Context, repoURL, ref, featureID string) (*domain.FeatureSnapshot, error) {
417	+	owner, repo, err := parseRepoURL(repoURL)
418	+	if err != nil {
419	+		return nil, *err
420	+	}
421	+	c := newClient(a.token)
422	+
423	+	// Resolve commit SHA.
424	+	commitSHA, ferr := c.getCommitSHA(ctx, owner, repo, ref)
425	+	if ferr != nil {
426	+		return nil, mapFetchError(ferr, owner, repo)
427	+	}
428	+
429	+	// Get the full tree to discover task YAMLs for this feature.
430	+	tree, ferr := c.getTree(ctx, owner, repo, commitSHA)
431	+	if ferr != nil {
432	+		return nil, mapFetchError(ferr, owner, repo)
433	+	}
434	+
435	+	pathSet := make(map[string]struct{}, len(tree.Tree))
436	+	for _, e := range tree.Tree {
437	+		if e.Type == "blob" {
438	+			pathSet[e.Path] = struct{}{}
439	+		}
440	+	}
441	+
442	+	snap, errs := a.fetchFeature(ctx, c, owner, repo, ref, featureID, pathSet)
443	+	if len(errs) > 0 {
444	+		// Return the first hard error if snap is nil.
445	+		if snap == nil {
446	+			return nil, errs[0]
447	+		}
448	+		// Soft errors (e.g. optional files missing) are ignored for targeted sync.
449	+	}
450	+	if snap == nil {
451	+		return nil, domain.NewGitHubNotFoundError("https://github.com/" + owner + "/" + repo)
452	+	}
453	+	return snap, nil
454	+}
