970	+// VerifySignature checks the X-Hub-Signature-256 header against the request body.
971	+// Returns an error if the signature is missing or invalid.
972	+func VerifySignature(secret string, header string, body []byte) error {
973	+	if secret == "" {
974	+		return nil
975	+	}
976	+	const prefix = "sha256="
977	+	if !strings.HasPrefix(header, prefix) {
978	+		return fmt.Errorf("missing or malformed X-Hub-Signature-256 header")
979	+	}
980	+	gotHex := strings.TrimPrefix(header, prefix)
981	+	mac := hmac.New(sha256.New, []byte(secret))
982	+	mac.Write(body)
983	+	wantHex := hex.EncodeToString(mac.Sum(nil))
984	+	if !hmac.Equal([]byte(gotHex), []byte(wantHex)) {
985	+		return fmt.Errorf("webhook signature mismatch")
986	+	}
987	+	return nil
988	+}
989	+
990	+// ReadAndVerify reads the request body and verifies the GitHub HMAC signature.
991	+// Returns the raw body bytes on success. The caller must not call r.Body.Read again.
992	+func ReadAndVerify(r *http.Request, secret string) ([]byte, error) {
993	+	body, err := io.ReadAll(r.Body)
994	+	if err != nil {
995	+		return nil, fmt.Errorf("read webhook body: %w", err)
996	+	}
997	+	sig := r.Header.Get("X-Hub-Signature-256")
998	+	if err := VerifySignature(secret, sig, body); err != nil {
999	+		return nil, err
1000	+	}
1001	+	return body, nil
1002	+}
