+		{"refs/heads/feature/workspace-data-backend-T7", "feature/workspace-data-backend-T7"},
+		{"main", "main"},
+	}
+	for _, tc := range cases {
+		got := webhook.BranchFromRef(tc.ref)
+		if got != tc.want {
+			t.Errorf("BranchFromRef(%q) = %q, want %q", tc.ref, got, tc.want)
+		}
+	}
+}
